<script setup>
import {ref,reactive,computed,watch,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {api,session} from '../api'
import Icon from '../components/Icon.vue'
import GradeTable from '../components/GradeTable.vue'
const props=defineProps({kind:String}),route=useRoute()
const rows=ref([]),total=ref(0),lastPage=ref(1),page=ref(1),search=ref(''),group=ref(route.query.group?Number(route.query.group):null),busy=ref(false),saving=ref(false),error=ref(''),formError=ref(''),notice=ref(''),modal=ref(false),confirm=ref(null),options=ref({groups:[],students:[],teachers:[]}),form=reactive({})
const config=computed(()=>({grades:{title:session.user?.role==='student'?'Mis notas':'Gestión de notas',subtitle:'Cada evaluación, organizada y al alcance de tu mano.',singular:'nota',icon:'BookOpen'},teachers:{title:'Docentes',subtitle:'Gestiona al equipo que acompaña el aprendizaje.',singular:'docente',icon:'UserRound'},students:{title:'Estudiantes',subtitle:'Administra la comunidad estudiantil y sus inscripciones.',singular:'estudiante',icon:'Users'},groups:{title:'Grupos académicos',subtitle:'Organiza las asignaturas, ciclos y docentes responsables.',singular:'grupo',icon:'Layers'}}[props.kind]))
const canCreate=computed(()=>(props.kind==='grades'&&session.user?.role!=='student')||session.user?.role==='admin')
const groupOptions=computed(()=>options.value.groups.map(g=>({title:g.code+' · '+g.subject,value:g.id})))
const studentOptions=computed(()=>{const selected=options.value.groups.find(g=>g.id===form.academic_group_id);return (selected?.students||[]).map(s=>({title:s.student_code+' · '+s.name,value:s.id}))})
async function load(){busy.value=true;error.value='';try{const q=new URLSearchParams({page:page.value,search:search.value});if(props.kind==='grades'&&group.value)q.set('group_id',group.value);const [d,o]=await Promise.all([api('/'+props.kind+'?'+q),api('/options')]);rows.value=d.data;total.value=d.total;lastPage.value=d.last_page;options.value=o}catch(e){error.value=e.message}finally{busy.value=false}}
watch(()=>props.kind,()=>{page.value=1;search.value='';group.value=null;notice.value='';load()});watch(page,load);onMounted(load)
function filter(){if(page.value!==1)page.value=1;else load()}
function open(row=null){Object.keys(form).forEach(k=>delete form[k]);formError.value='';if(row){Object.assign(form,JSON.parse(JSON.stringify(row)));if(props.kind==='students')form.group_ids=row.groups.map(g=>g.id)}else Object.assign(form,{name:'',email:'',phone:'',student_code:'',career:'Licenciatura en ciencias de la computacion',group_ids:[],code:'',subject:'',cycle:'II-2026',teacher_id:null,student_id:null,academic_group_id:group.value||null,evaluation:1,score:null,recorded_on:new Intl.DateTimeFormat('sv-SE',{timeZone:'America/El_Salvador'}).format(new Date()),observations:''});modal.value=true}
async function save(){saving.value=true;formError.value='';try{const fields={grades:['student_id','academic_group_id','evaluation','score','recorded_on','observations'],teachers:['name','email','phone'],students:['name','email','student_code','career','group_ids'],groups:['code','subject','cycle','teacher_id']}[props.kind];const body=Object.fromEntries(fields.map(k=>[k,form[k]]));const d=await api('/'+props.kind+(form.id?'/'+form.id:''),{method:form.id?'PUT':'POST',body});modal.value=false;notice.value=d.message||`${config.value.singular[0].toUpperCase()+config.value.singular.slice(1)} ${form.id?'actualizado':'registrado'} correctamente.`;await load()}catch(e){formError.value=Object.values(e.errors||{}).flat().join(' ')||e.message}finally{saving.value=false}}
function ask(action,row){confirm.value={action,row}}
async function execute(){if(saving.value)return;saving.value=true;try{const {action,row}=confirm.value;const path='/'+props.kind+'/'+row.id+(action==='email'?'/email':action==='invite'?'/invite':action==='reset'?'/reset-access':'');const d=await api(path,{method:action==='delete'?'DELETE':'POST'});notice.value=d.message;confirm.value=null;if(action==='delete'&&rows.value.length===1&&page.value>1)page.value--;else await load()}catch(e){error.value=e.message;confirm.value=null}finally{saving.value=false}}
function initials(name){return name?.split(' ').slice(0,2).map(x=>x[0]).join('')}
</script>
<template><div class="page-heading"><div><span class="eyebrow">ADMINISTRACIÓN ACADÉMICA</span><h1>{{config.title}}<span class="heading-dot">.</span></h1><p>{{config.subtitle}}</p></div><v-btn v-if="canCreate" color="primary" size="large" @click="open()"><Icon name="Plus" :size="18" class="mr-2"/>{{kind==='grades'?'Registrar nota':kind==='students'?'Crear estudiante':'Nuevo '+config.singular}}</v-btn></div>
 <v-alert v-if="error" type="error" variant="tonal" closable class="mb-5" @click:close="error=''">{{error}}</v-alert><v-alert v-if="notice" type="success" variant="tonal" closable class="mb-5" @click:close="notice=''">{{notice}}</v-alert>
 <div v-if="kind==='teachers'||kind==='students'" class="info-strip"><Icon name="Mail" :size="22"/><div><strong>Un inicio seguro para cada {{kind==='teachers'?'docente':'estudiante'}}</strong><p>Al crear una cuenta, enviaremos por correo sus credenciales temporales y el enlace para configurar Google Authenticator.</p></div></div>
 <section class="panel records-panel"><div class="records-toolbar"><div class="records-title"><span class="list-icon"><Icon :name="config.icon"/></span><h2>{{kind==='grades'?'Registro de evaluaciones':'Directorio de '+(kind==='groups'?'grupos':config.title.toLowerCase())}}</h2><span class="count-badge">{{total}}</span></div><div class="records-filters"><form class="search-field" @submit.prevent="filter"><Icon name="Search" :size="17"/><input v-model="search" :placeholder="kind==='grades'||kind==='students'?'Buscar estudiante o carné…':'Buscar por nombre…'" aria-label="Buscar registros"/><button type="submit" class="search-submit" title="Buscar"><Icon name="ArrowRight" :size="16"/></button></form><v-select v-if="kind==='grades'" v-model="group" :items="groupOptions" label="Todos los grupos" hide-details clearable class="group-select" @update:model-value="filter"/></div></div>
 <v-progress-linear v-if="busy" indeterminate color="primary"/>
 <GradeTable v-if="kind==='grades'" :rows="rows" :actions="canCreate" @edit="open" @remove="ask('delete',$event)" @email="ask('email',$event)"/>
 <div v-else class="table-scroll"><table class="data-table"><thead><tr><th>{{kind==='teachers'?'DOCENTE':kind==='students'?'ESTUDIANTE':'GRUPO / ASIGNATURA'}}</th><th>{{kind==='groups'?'DOCENTE RESPONSABLE':'CORREO ELECTRÓNICO'}}</th><th>{{kind==='teachers'?'TELÉFONO':kind==='students'?'CARRERA':'CICLO'}}</th><th>{{kind==='teachers'?'ESTADO':kind==='students'?'GRUPOS':'ESTUDIANTES'}}</th><th v-if="kind==='students'">ESTADO DE ACTIVACIÓN</th><th v-if="canCreate" class="text-right">ACCIONES</th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="row.id"><td><div class="student-cell"><span class="student-avatar" :class="'tone-'+i%4"><Icon v-if="kind==='groups'" name="BookOpen" :size="20"/><template v-else>{{initials(row.name)}}</template></span><div><strong>{{kind==='groups'?row.subject:row.name}}</strong><small>{{row.student_code||row.code||'Docente ULS'}}</small></div></div></td><td>{{kind==='groups'?row.teacher?.name:row.email}}</td><td>{{kind==='groups'?row.cycle:kind==='students'?row.career:row.phone||'Sin registrar'}}</td><td><span v-if="kind==='teachers'" class="status-badge" :class="row.totp_confirmed_at?'passed':'pending'"><span></span>{{row.totp_confirmed_at?'Cuenta activa':'Por activar'}}</span><span v-else-if="kind==='students'" class="subtext">{{row.groups.map(g=>g.code).join(', ')||'Sin inscripciones'}}</span><span v-else class="evaluation-chip">{{row.students_count}} estudiantes</span></td><td v-if="kind==='students'"><span class="status-badge" :class="row.totp_confirmed_at?'passed':'pending'"><span></span>{{row.totp_confirmed_at?'Cuenta activa':'Por activar'}}</span></td><td v-if="canCreate"><div class="row-actions"><button v-if="kind==='teachers'||kind==='students'" @click="ask('invite',row)" title="Reenviar correo" aria-label="Reenviar correo"><Icon name="Mail" :size="17"/><span>Reenviar correo</span></button><button v-if="kind==='teachers'||kind==='students'" @click="ask('reset',row)" title="Restablecer acceso y generar QR nuevo" aria-label="Restablecer acceso y generar QR nuevo"><Icon name="QrCode" :size="17"/><span>Restablecer QR</span></button><button @click="open(row)" title="Editar" aria-label="Editar"><Icon name="Pencil" :size="17"/><span>Editar</span></button><button class="danger" @click="ask('delete',row)" title="Eliminar" aria-label="Eliminar"><Icon name="Trash2" :size="17"/></button></div></td></tr><tr v-if="!rows.length&&!busy"><td :colspan="kind==='students'?6:5"><div class="empty-state"><Icon :name="config.icon" :size="32"/><strong>No encontramos registros</strong><p>Prueba otra búsqueda o registra un nuevo {{config.singular}}.</p></div></td></tr></tbody></table></div>
 <div class="pagination-bar"><p>Mostrando <strong>{{total?(page-1)*5+1:0}}–{{Math.min(page*5,total)}}</strong> de <strong>{{total}}</strong> registros</p><div class="pagination-controls"><span>5 por página</span><button :disabled="page<=1||busy" @click="page--" aria-label="Página anterior"><Icon name="ChevronLeft" :size="17"/></button><v-pagination v-model="page" :length="lastPage" :total-visible="4" size="small" :show-first-last-page="false" active-color="primary"/><button :disabled="page>=lastPage||busy" @click="page++" aria-label="Página siguiente"><Icon name="ChevronRight" :size="17"/></button></div></div></section>
 <p class="table-help"><Icon name="ShieldCheck" :size="15"/>{{kind==='grades'?'Las notas se validan en una escala de 0 a 10. La nota mínima de aprobación es 6.00.':'Los datos de la comunidad académica se mantienen protegidos.'}}</p>
 <v-dialog v-model="modal" max-width="640" scrollable><v-card><div class="modal-heading"><div><span class="eyebrow">{{config.title}}</span><h2>{{form.id?'Editar':'Registrar'}} {{config.singular}}</h2></div><button @click="modal=false" aria-label="Cerrar formulario"><Icon name="X"/></button></div><v-card-text><v-alert v-if="formError" type="error" variant="tonal" class="mb-5">{{formError}}</v-alert><form id="record-form" @submit.prevent="save">
 <template v-if="kind==='grades'"><v-select v-model="form.academic_group_id" :items="groupOptions" label="Grupo y asignatura" required @update:model-value="form.student_id=null"/><v-select v-model="form.student_id" :items="studentOptions" label="Estudiante inscrito" :disabled="!form.academic_group_id" required/><div class="form-grid"><v-select v-model="form.evaluation" :items="[{title:'Parcial 1',value:1},{title:'Parcial 2',value:2},{title:'Parcial 3',value:3}]" label="Evaluación" required/><v-text-field v-model.number="form.score" type="number" label="Nota (0 a 10)" min="0" max="10" step="0.01" required/></div><v-text-field v-model="form.recorded_on" label="Fecha de registro" type="date" required/><v-textarea v-model="form.observations" label="Observaciones (opcional)" variant="outlined" rows="2" maxlength="1000"/></template>
 <template v-if="kind==='teachers'||kind==='students'"><v-text-field v-model="form.name" label="Nombre completo" maxlength="150" required/><v-text-field v-model="form.email" label="Correo electrónico" type="email" maxlength="255" required/><v-text-field v-if="kind==='teachers'" v-model="form.phone" label="Teléfono (opcional)" maxlength="25"/><template v-else><div class="form-grid"><v-text-field v-model="form.student_code" label="Carné" maxlength="20" required/><v-text-field v-model="form.career" label="Carrera" readonly required/></div><v-select v-model="form.group_ids" :items="groupOptions" multiple chips label="Inscribir en grupos"/></template></template>
 <template v-if="kind==='groups'"><v-text-field v-model="form.subject" label="Nombre de la asignatura" maxlength="150" required/><div class="form-grid"><v-text-field v-model="form.code" label="Código del grupo" maxlength="30" required/><v-text-field v-model="form.cycle" label="Ciclo académico" maxlength="20" required/></div><v-select v-model="form.teacher_id" :items="options.teachers.map(t=>({title:t.name,value:t.id}))" label="Docente responsable" required/></template>
 <div v-if="(kind==='teachers'||kind==='students')&&!form.id" class="form-notice"><Icon name="Mail" :size="20"/> La contraseña temporal se genera automáticamente y se envía por correo.</div>
 </form></v-card-text><div class="modal-footer"><v-btn variant="text" @click="modal=false">Cancelar</v-btn><v-btn color="primary" type="submit" form="record-form" :loading="saving">{{(kind==='teachers'||kind==='students')&&!form.id?'Crear '+config.singular+' y enviar correo':'Guardar '+config.singular}}</v-btn></div></v-card></v-dialog>
 <v-dialog :persistent="saving" :model-value="!!confirm" @update:model-value="!$event&&(confirm=null)" max-width="460"><v-card class="pa-7"><span class="confirm-icon"><Icon :name="confirm?.action==='delete'?'TriangleAlert':confirm?.action==='reset'?'QrCode':'Mail'" :size="27"/></span><h2 class="mt-4 mb-3">{{confirm?.action==='delete'?'¿Eliminar este registro?':confirm?.action==='reset'?'¿Restablecer acceso y QR?':confirm?.action==='invite'?'¿Reenviar correo?':'¿Enviar nota por correo?'}}</h2><p class="confirm-description">{{confirm?.action==='delete'?'Esta acción eliminará el registro seleccionado. Los datos con dependencias se conservarán.':confirm?.action==='reset'?'Se enviarán un QR nuevo y una contraseña temporal a '+confirm.row.email+'. El autenticador, la contraseña y las sesiones anteriores dejarán de funcionar. El usuario deberá volver a configurar Google Authenticator y cambiar su clave.':confirm?.action==='invite'?'La cuenta pendiente recibirá una nueva invitación y contraseña temporal. Si ya está activa, recibirá el enlace de ingreso sin cambiar su contraseña ni su autenticador.':'El estudiante recibirá los detalles de esta evaluación en su correo registrado.'}}</p><div class="d-flex justify-end ga-3 mt-6"><v-btn variant="text" :disabled="saving" @click="confirm=null">Cancelar</v-btn><v-btn :color="confirm?.action==='delete'?'error':'primary'" :loading="saving" @click="execute">{{confirm?.action==='delete'?'Eliminar':confirm?.action==='reset'?'Generar QR y enviar':'Enviar correo'}}</v-btn></div></v-card></v-dialog>
</template>
